import {escapeHTML as e,money} from './core.mjs';
export function renderImportView(s,{result,check,duplicate,valid,dateLabel}){
 const ts=result.transactions,ds=ts.map(t=>t.date).sort(),headers=s.rows[s.header]||[],maxCols=Math.max(headers.length,...s.rows.slice(s.header+1,s.header+12).map(r=>r.length));
 const columns=selected=>'<option value="-1">Not present</option>'+Array.from({length:maxCols},(_,i)=>`<option value="${i}" ${selected===i?'selected':''}>${i+1}: ${e(String(headers[i]??'(unnamed)').slice(0,60))}</option>`).join('');
 const opt=(values,selected)=>values.map(([v,label])=>`<option value="${e(v)}" ${v===selected?'selected':''}>${e(label)}</option>`).join('');
 const needsReview=s.usedOCR||s.warnings?.length||result.counts.invalid>0||(check.available&&check.errors.length>0)||result.issues?.some(i=>i.severity==='warning');
 const warnings=[...(s.warnings||[]),...(result.warnings||[])];
 const page=s.rawPage||0,size=12,start=s.header+1+page*size,raw=s.rows.slice(start,start+size);
 return `<div class="dialog-head"><div><div class="eyebrow">UPLOAD → MATCH COLUMNS → REVIEW → EXPLORE</div><h2 id="import-title">Make this statement yours.</h2><p>${e(s.name)} · ${s.usedOCR?'Text recognized from an image':'File read locally'} · INR</p></div><button class="close-dialog" data-close="import-dialog" aria-label="Close import">×</button></div>
 <div class="note-box">Your file stays on this device. Choose the account label carefully: reuse a label for statements from the same account; give different accounts different labels. This analysis supports <b>Indian rupees (INR)</b>.</div>
 <div class="import-controls"><label class="field">Table<select data-import="sheet">${opt(s.sheetNames.map(n=>[n,n]),s.sheet)}</select></label><label class="field">Header row<input data-import="header" type="number" min="1" max="${s.rows.length}" value="${s.header+1}"></label><label class="field">Account type<select data-import="account">${opt([['bank','Bank account'],['card','Credit card']],s.account)}</select></label><label class="field">Account label<input data-import="accountKey" value="${e(s.accountKey)}" maxlength="80" placeholder="e.g. HDFC savings • 1234"><small>Use a nickname or last four digits.</small></label><label class="field">Date order<select data-import="dateOrder">${opt([['DMY','Day / month / year'],['MDY','Month / day / year']],s.dateOrder)}</select></label><label class="field">Amount layout<select data-import="layout">${opt([['split','Separate money out / money in'],['signed','One amount column']],s.layout)}</select></label></div>
 <div class="mapping-grid">${[['date','Transaction date'],['description','Description / narration'],['balance','Running balance (optional)'],...(s.layout==='split'?[['debit','Money out / debit'],['credit','Money in / credit']]:[['amount','Amount'],['type','Debit / credit flag (optional)']])].map(([key,label])=>`<label>${label}<select data-map="${key}">${columns(s.map[key])}</select></label>`).join('')}${s.layout==='signed'?`<label>When a row has no debit / credit flag<select data-import="sign">${opt([['debit-positive','Positive = money out'],['credit-positive','Positive = money in']],s.sign)}</select></label>`:''}</div>
 ${(result.schemaErrors||[]).map(msg=>`<div class="error-box">${e(msg)}</div>`).join('')}
 ${warnings.length?`<div class="note-box"><b>Check before importing</b><ul>${[...new Set(warnings)].map(w=>`<li>${e(w)}</li>`).join('')}</ul></div>`:''}
 <div class="import-summary"><div><span>Transactions found</span><strong>${ts.length.toLocaleString('en-IN')}</strong></div><div><span>Money out</span><strong>${money(ts.reduce((a,t)=>a+t.debit,0))}</strong></div><div><span>Money in</span><strong>${money(ts.reduce((a,t)=>a+t.credit,0))}</strong></div></div>
 <p class="panel-note">${dateLabel(ds[0])} — ${dateLabel(ds.at(-1))} · ${duplicate} exact overlaps · ${result.counts.nonTransactions} non-transaction rows · ${result.counts.zero} zero-amount rows</p>
 ${result.counts.invalid?`<div class="error-box"><b>${result.counts.invalid} rows could not be parsed.</b> Correct them in the extracted table below or acknowledge that they will be excluded.${(result.issues||[]).filter(i=>i.severity==='error').slice(0,6).map(i=>`<div>Row ${i.row}: ${e(i.reason)}</div>`).join('')}</div>`:''}
 ${check.available?`<div class="${check.errors.length?'error-box':'note-box'}">${check.errors.length?`<b>${check.errors.length} running-balance differences.</b> Check the dates, debit/credit mapping and amounts against your statement.`:`Running balances are consistent across ${check.count} transactions. The opening balance is inferred from the first row, so check that row against your statement.`}</div>`:'<p class="panel-note" style="margin:14px 0">No running-balance check is available. Compare the totals with your original statement.</p>'}
 <details class="extracted-table" ${s.rawOpen?'open':''}><summary>Inspect or correct the extracted table${s.usedOCR?' — recommended after text recognition':''}</summary><p class="panel-note">Edit a cell, then leave it to recalculate the preview. Rows refer to the extracted table; PDF page numbers appear in transaction details.</p><div class="import-preview"><table><thead><tr><th>Row</th>${Array.from({length:maxCols},(_,i)=>`<th>${e(headers[i]??'Column '+(i+1))}</th>`).join('')}</tr></thead><tbody>${raw.map((r,i)=>`<tr><th>${start+i+1}</th>${Array.from({length:maxCols},(_,j)=>`<td><input aria-label="Row ${start+i+1}, column ${j+1}" data-raw-row="${start+i}" data-raw-col="${j}" value="${e(r[j] instanceof Date?r[j].toISOString().slice(0,10):r[j]??'')}"></td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="pagination"><span>Rows ${raw.length?start+1:0}–${start+raw.length} of ${s.rows.length}</span><div class="buttons"><button class="button small" data-raw-step="-1" ${page===0?'disabled':''}>Previous rows</button><button class="button small" data-raw-step="1" ${start+size>=s.rows.length?'disabled':''}>Next rows</button></div></div></details>
 <h3 class="import-preview-heading">Transaction preview</h3><div class="import-preview"><table><thead><tr><th>Date</th><th>Merchant</th><th>Money out</th><th>Money in</th></tr></thead><tbody>${ts.slice(0,8).map(t=>`<tr><td>${dateLabel(t.date)}</td><td>${e(t.merchant)}</td><td>${money(t.debit)}</td><td>${money(t.credit)}</td></tr>`).join('')||'<tr><td colspan="4">No transactions yet. Check the header row and column mapping.</td></tr>'}</tbody></table></div>
 ${needsReview?`<label class="import-ack"><input type="checkbox" id="import-reviewed" ${s.reviewed?'checked':''}>I checked the recognized text, totals and any excluded rows against the original statement.</label>`:''}
 <div class="dialog-actions"><label>Import mode<select data-import="mode">${opt([['merge','Merge, skipping exact overlaps'],['replace','Replace this analysis']],s.mode)}</select></label><button class="button" data-close="import-dialog">Cancel</button><button class="button primary" data-action="confirm-import" ${valid&&(!needsReview||s.reviewed)?'':'disabled'}>Add ${ts.length.toLocaleString('en-IN')} transactions</button></div><p class="panel-note" style="margin-top:14px">Categories are suggestions from transaction descriptions. You can correct them after import. Keep a backup to move this analysis to another browser.</p>`;
}
